// ServerlessWorkflowValidation contains the generated Serverless Workflow YAML
//
//	and its validation state. This is populated asynchronously after workflow creation
//	via a Temporal workflow that validates the workflow structure.
type ServerlessWorkflowValidation struct {
	// Current validation state
	State string `json:"state,omitempty"`
	// Generated Serverless Workflow YAML (CNCF DSL 1.0.0 format)  This YAML may contain runtime expressions for environment variables:    Example: ${ .env.API_BASE_URL }   Present even if validation failed (helps debugging).  Empty if validation hasn't started yet.
	Yaml string `json:"yaml,omitempty"`
	// Validation errors (empty if valid)  Examples:    - "Invalid YAML syntax at line 15"    - "Unknown task type 'invalid_task'"    - "Missing required field: document.namespace"
	Errors []string `json:"errors,omitempty"`
	// Non-fatal warnings  Examples:    - "Environment variable API_KEY referenced but not defined"    - "Task 'fetchData' has no error handling"
	Warnings []string `json:"warnings,omitempty"`
	// When validation was performed  Null if validation hasn't completed yet
	ValidatedAt *timestamppb.Timestamp `json:"validatedAt,omitempty"`
	// Temporal workflow ID for the validation workflow  Format: "validate-workflow-{workflow_id}"  Useful for tracking/debugging validation progress
	ValidationWorkflowId string `json:"validationWorkflowId,omitempty"`
}

